import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { pipeline } from "node:stream/promises";
import type { Readable } from "node:stream";
import { DeleteObjectCommand, GetObjectCommand, HeadObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import type { AppConfig } from "./config.js";

/**
 * Object keys are generated by the server only, never taken from requests.
 * The pattern rejects traversal and anything outside the expected layout.
 */
const KEY_PATTERN = /^(users\/[a-f0-9]{24}\/(projects\/[a-f0-9]{24}\/)?|cache\/)[A-Za-z0-9._\-/]{1,200}$/;

export function assertValidKey(key: string): string {
  if (!KEY_PATTERN.test(key) || key.includes("..") || key.includes("//")) throw new Error(`Invalid storage key: ${key}`);
  return key;
}

export function newObjectKey(parts: { userId: string; projectId?: string; folder: string; ext: string }): string {
  const id = crypto.randomBytes(12).toString("hex");
  const folder = parts.folder.replace(/[^a-z0-9-]/g, "");
  const ext = parts.ext.replace(/[^a-z0-9]/g, "");
  const base = parts.projectId ? `users/${parts.userId}/projects/${parts.projectId}` : `users/${parts.userId}`;
  return assertValidKey(`${base}/${folder}/${id}.${ext}`);
}

export interface StoredObjectInfo {
  sizeBytes: number;
}

export interface DownloadTarget {
  /** Serve a local file through the API (local driver); supports HTTP range requests. */
  filePath?: string;
  /** Redirect the client to a short-lived signed URL (S3 driver). */
  redirectUrl?: string;
  sizeBytes: number;
}

export interface StorageDriver {
  readonly id: "local" | "s3";
  putFile(key: string, filePath: string, mimeType: string): Promise<StoredObjectInfo>;
  /** Local filesystem path for the object; downloads to `workDir` for remote drivers. */
  materialize(key: string, workDir: string): Promise<string>;
  exists(key: string): Promise<boolean>;
  delete(key: string): Promise<void>;
  download(key: string, filename: string, mimeType: string): Promise<DownloadTarget>;
  check(): Promise<{ ok: boolean; detail?: string }>;
}

export class LocalStorage implements StorageDriver {
  readonly id = "local" as const;
  constructor(private readonly root: string) {
    fs.mkdirSync(root, { recursive: true });
  }

  private resolve(key: string): string {
    const p = path.resolve(this.root, assertValidKey(key));
    if (!p.startsWith(path.resolve(this.root) + path.sep)) throw new Error("Storage path escapes root");
    return p;
  }

  async putFile(key: string, filePath: string): Promise<StoredObjectInfo> {
    const dest = this.resolve(key);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    const tmp = `${dest}.${process.pid}.tmp`;
    await fs.promises.copyFile(filePath, tmp);
    await fs.promises.rename(tmp, dest);
    return { sizeBytes: (await fs.promises.stat(dest)).size };
  }

  async materialize(key: string): Promise<string> {
    const p = this.resolve(key);
    if (!fs.existsSync(p)) throw new Error(`Stored object missing: ${key}`);
    return p;
  }

  async exists(key: string): Promise<boolean> {
    return fs.existsSync(this.resolve(key));
  }

  async delete(key: string): Promise<void> {
    await fs.promises.rm(this.resolve(key), { force: true });
  }

  async download(key: string): Promise<DownloadTarget> {
    const p = this.resolve(key);
    const st = await fs.promises.stat(p);
    return { filePath: p, sizeBytes: st.size };
  }

  async check() {
    try {
      const probe = path.join(this.root, ".write-check");
      await fs.promises.writeFile(probe, "ok");
      await fs.promises.rm(probe);
      return { ok: true, detail: "local filesystem" };
    } catch (e) {
      return { ok: false, detail: (e as Error).message };
    }
  }
}

/** S3-compatible storage (AWS S3, Cloudflare R2, MinIO). Implemented but not exercised by the automated tests. */
export class S3Storage implements StorageDriver {
  readonly id = "s3" as const;
  private readonly client: S3Client;

  constructor(private readonly config: AppConfig) {
    this.client = new S3Client({
      region: config.S3_REGION,
      endpoint: config.S3_ENDPOINT || undefined,
      forcePathStyle: config.S3_FORCE_PATH_STYLE,
      credentials:
        config.S3_ACCESS_KEY_ID && config.S3_SECRET_ACCESS_KEY
          ? { accessKeyId: config.S3_ACCESS_KEY_ID, secretAccessKey: config.S3_SECRET_ACCESS_KEY }
          : undefined,
    });
  }

  private get bucket(): string {
    return this.config.S3_BUCKET!;
  }

  async putFile(key: string, filePath: string, mimeType: string): Promise<StoredObjectInfo> {
    const size = (await fs.promises.stat(filePath)).size;
    await this.client.send(new PutObjectCommand({ Bucket: this.bucket, Key: assertValidKey(key), Body: fs.createReadStream(filePath), ContentType: mimeType, ContentLength: size }));
    return { sizeBytes: size };
  }

  async materialize(key: string, workDir: string): Promise<string> {
    const dest = path.join(workDir, "s3-cache", assertValidKey(key));
    if (fs.existsSync(dest)) return dest;
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    const res = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    const tmp = `${dest}.tmp`;
    await pipeline(res.Body as Readable, fs.createWriteStream(tmp));
    fs.renameSync(tmp, dest);
    return dest;
  }

  async exists(key: string): Promise<boolean> {
    try {
      await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: assertValidKey(key) }));
      return true;
    } catch {
      return false;
    }
  }

  async delete(key: string): Promise<void> {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: assertValidKey(key) }));
  }

  async download(key: string, filename: string, mimeType: string): Promise<DownloadTarget> {
    const head = await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: assertValidKey(key) }));
    const url = await getSignedUrl(
      this.client,
      new GetObjectCommand({ Bucket: this.bucket, Key: key, ResponseContentType: mimeType, ResponseContentDisposition: `attachment; filename="${filename.replace(/[^A-Za-z0-9._-]/g, "_")}"` }),
      { expiresIn: this.config.DOWNLOAD_URL_TTL_SECONDS },
    );
    return { redirectUrl: url, sizeBytes: head.ContentLength ?? 0 };
  }

  async check() {
    try {
      await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: "cache/.healthcheck" }));
      return { ok: true, detail: `s3://${this.bucket}` };
    } catch (e) {
      const status = (e as { $metadata?: { httpStatusCode?: number } }).$metadata?.httpStatusCode;
      // 404 means the bucket is reachable and the probe object simply does not exist.
      return status === 404 ? { ok: true, detail: `s3://${this.bucket}` } : { ok: false, detail: (e as Error).message };
    }
  }
}

export function createStorage(config: AppConfig): StorageDriver {
  return config.STORAGE_DRIVER === "s3" ? new S3Storage(config) : new LocalStorage(config.STORAGE_LOCAL_DIR);
}
